import {insightSearchCommands} from './insight-search.js';
import {feedCommand,inboxCommand} from './insight-activity.js';
import {exportCommand,importCommand,dashboardCommand} from './insight-transfer.js';
export const commands={...insightSearchCommands,feed:feedCommand,inbox:inboxCommand,export:exportCommand,import:importCommand,dashboard:dashboardCommand};

import {registerDashboardRoutes} from './dashboards.js';
import {registerTransferRoutes} from './transfer.js';
import {registerSearchRoutes} from './search-routes.js';
import {registerFilterRoutes} from './filter-routes.js';
import {persistActivity,listActivity} from './activity.js';
import {notifyActivity,registerNotificationRoutes} from './notifications.js';
import {registerSubscriptionRoutes} from './subscriptions.js';
import {registerDigestRoutes} from './digests.js';
export function registerRoutes(ctx) {
  const unsubscribe=ctx.bus.subscribe(event=>{
    const activity=persistActivity(ctx,event);
    if(activity)notifyActivity(ctx,event,activity);
  });
  (ctx.cleanups??=[]).push(unsubscribe);
  ctx.app.get('/api/v1/activity',ctx.requireAuth,(req,res)=>res.json(listActivity(ctx,req,req.query)));
  registerSubscriptionRoutes(ctx);
  registerNotificationRoutes(ctx);
  registerDigestRoutes(ctx);
  registerSearchRoutes(ctx);
  registerFilterRoutes(ctx);
  registerDashboardRoutes(ctx);
  registerTransferRoutes(ctx);
}

import {DashboardPage} from './dashboard.jsx';
import {TransferPage} from './transfer.jsx';
import {InboxPage} from './inbox.jsx';
import {searchRoutes,searchNavigation} from './search-routes.jsx';
import {ActivityPage} from './activity.jsx';
import '../../styles/insight-activity.css';
export const routes=[...searchRoutes,{path:'/activity',component:ActivityPage},{path:'/inbox',component:InboxPage},{path:'/dashboard',component:DashboardPage},{path:'/transfer',component:TransferPage}];
export const navigation=[...searchNavigation,{path:'/activity',label:'Activity'},{path:'/inbox',label:'Inbox'},{path:'/dashboard',label:'Dashboard'},{path:'/transfer',label:'Transfer'}];
